"""Regenerate the handoff from measurement files and the audited requirement matrix."""
import collections,datetime,json,platform,re,shutil,subprocess
from pathlib import Path
root=Path(__file__).resolve().parents[1]
def read(relative):return json.loads((root/relative).read_text())
matrix=(root/'docs/role-evidence-matrix.md').read_text();rows=[]
for line in matrix.splitlines():
    if not re.match(r'\| (?:R|X|H)\d\d \|',line):continue
    fields=[x.strip() for x in line.strip('|').split('|')];rows.append({'id':fields[0],'category':fields[1],'status':fields[-1]})
counts=collections.Counter(r['status'] for r in rows)
for status in counts:
    if status not in {'implemented-tested','implemented-unverified','deferred','unavailable'}:raise ValueError('Invalid matrix status '+status)
complete=counts['implemented-tested'];partial=counts['implemented-unverified']+counts['deferred'];blocked=counts['unavailable']
bench=read('reports/bench/formal/timing-index.json')
if bench['status']!='verified':raise ValueError('Formal timing suite not finished')
sem=read('reports/semantic-heldout.json');det=read('reports/detection-heldout.json');fixture=read('reports/motion/fixture-observed-world-budgeted-summary.json');jaad=read('reports/motion/jaad-observed-image-budgeted-summary.json');ablation=read('reports/pipeline-ablations.json')
size=sum(p.stat().st_size for p in root.rglob('*') if p.is_file() and not p.is_symlink());free=shutil.disk_usage(root).free;ledger=[json.loads(s) for s in (root/'reports/data/download_ledger.jsonl').read_text().splitlines()];download=ledger[-1]['cumulative_bytes']
if size>=8_000_000_000 or free<15_000_000_000 or download+1_000_000_000>=8_000_000_000:raise RuntimeError('Final budget failed')
report={'overall_status':'PARTIAL','updated_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'requirements':rows,'counts':{'Complete':complete,'Partial':partial,'Blocked':blocked,'status_counts':dict(counts)},'source_commit':subprocess.check_output(['git','rev-parse','HEAD'],cwd=root,text=True).strip(),'resources':{'project_bytes':size,'free_disk_bytes':free,'recorded_application_download_bytes':download,'unmetered_initial_dependency_reserve_bytes':1_000_000_000,'size_and_download_limit_bytes':8_000_000_000},'software_acceptance':'reports/acceptance.json','formal_benchmark':'reports/bench/formal/timing-index.json','demo':'demo/index.html','next_three_steps':['Collect an independently scene-disjoint real indoor labelled test set and freeze the evaluation before collecting new results.','Run the exported models on a named embedded target with the same held-out inputs, power/thermal/RAM and latency protocol.','Validate ROS2 and the perception-to-control interface on an authorized physical robot with recorded sensor checks before any actuation.'],'protocol_deviations':['Initial pip attempt used default cache before correction; later only hash-verified public wheel files were copied into local cache.','Excluded70epoch/batch128 fixture motion pilots and step0-selected JAAD checkpoints retained. Earlier test exposure is disclosed; corrected primary protocol was fixed without test-driven tuning.','Local Git initial history contains an excluded pilot checkpoint; do not distribute Git history or weights. The separate source-only bundle excludes both.']}
(root/'reports/final-audit.json').write_text(json.dumps(report,indent=2))
lines=['# Final handoff','',f'**Overall: PARTIAL. Complete / Partial / Blocked: {complete} / {partial} / {blocked}.** These count the scoped matrix rows, not model quality. Four unavailable rows concern industrial-team experience, physical robot, target embedded device and ROS2 execution.','',f'Generated from actual files at {report["updated_utc"]}. [Requirement matrix](docs/role-evidence-matrix.md), [software acceptance](reports/acceptance.json), [machine-readable audit](reports/final-audit.json).','',f'- Detection: held-out AP {det["trained"]["AP"]:.6f} versus COCO baseline {det["pretrained_baseline"]["AP"]:.6f},68 images/four JAAD clips. Three-seed results are descriptive, not proof of general indoor detection.',f'- Semantic: held-out mIoU {sem["trained"]["mIoU"]:.6f}, untrained head {sem["untrained_head"]["mIoU"]:.6f}, train-majority {sem["train_majority"]["mIoU"]:.6f}. Poor cross-scene generalization and below-majority pixel accuracy remain findings.','- Motion: fixture and JAAD have separate2x64 MLP packs, coordinate units and held-out evaluations. The fixture MLP improves over CV; the JAAD MLP does not. JAAD errors are conditional on53 matched supported windows in three clips, not whole-video end-to-end recall.',f'- Tracking: JAAD IDF1 {ablation["tracking"]["on"]["IDF1"]:.3f},14 ID switches on the fixed sparse68-frame scope. RGB-D fixture surface-range MAE is {ablation["distance"]["depth_assisted"]["surface_range_MAE_m"]:.6f}m; RGB-only metric range is unavailable.','- Export: real ONNX FP32 parity and static train-calibrated QDQ INT8 measured. Accuracy loss and timing/RAM/size tradeoffs are in the [formal benchmark](reports/bench/formal/timing-index.json). No embedded-device claim.','- Demo: [78.4-second local sensor-timeline viewer](demo/index.html),24 hash-verified panels; [scenario manifest](demo/scenario.json). Real TUM maps use supplied ground-truth camera poses; world X-Z projections are not calibrated bird\'s-eye views.','',f'Project size: {size/1e9:.3f}GB. Recorded application downloads: {download/1e9:.3f}GB plus1.000GB conservative reserve for unmetered initial dependency work. Free disk: {free/1e9:.2f}GB. Separate limits are8GB; disk reserve is15GB.','', 'The lab and bench are built and installed as noneditable wheels in independent local environments; bench has no lab installation. Exact dependency versions/hashes and own wheel hashes are recorded. [Install audit](reports/independent-source-audit.json).','', 'All launcher actions are verified only by real exit codes and log hashes in [the command ledger](reports/verified-commands.jsonl). Training checkpoints preserve optimizer, RNG and sampler state; actual interrupted continuation matched bitwise. MPS was verified only for a small convolution probe; primary neural runs and benchmarks use CPU.','', 'Protocol deviations are retained in [the audit](reports/final-audit.json) and [motion disclosure](reports/motion/README.md). Code assistance and the candidate\'s required review are disclosed in [my contribution](docs/my-contribution.md). No paid services, publication, uploads or robot actuation occurred. Original workspace Git status remained clean.','', 'Next three concrete steps:','']
lines += [f'{i}. {s}' for i,s in enumerate(report['next_three_steps'],1)]
(root/'FINAL_REPORT.md').write_text('\n'.join(lines)+'\n')
(root/'CHECKPOINT.md').write_text('# Checkpoint\n\nOverall: **PARTIAL**. Software acceptance and formal measurements completed.\n\n'+f'Updated{report["updated_utc"]}. Complete/Partial/Blocked {complete}/{partial}/{blocked}.\n\n'+f'Actual budget: project{size/1e9:.3f}GB; downloads{download/1e9:.3f}GB plus1GB reserve; free{free/1e9:.2f}GB.\n\n'+'Read FINAL_REPORT.md and reports/final-audit.json. No training/cache/inference acquisition jobs remain active. Do not restart completed experiments or tune from the held-out results. Physical robot, embedded target, ROS2 execution and industrial collaboration evidence remain unavailable. All prior deviations/failures are retained and disclosed.\n')
print(json.dumps({'overall':'PARTIAL','counts':report['counts'],'project_GB':size/1e9,'report':'FINAL_REPORT.md'}))
